import type { TabProps } from "./tab/tab.types";

import { forwardRef } from "react";
import { Add } from "@exp-textura/icons";

import { useTabBar } from "../hooks/use-tab-bar";

import { Tab } from "./tab";

export const TabBarAddTab = forwardRef<HTMLDivElement, TabProps>((props, ref) => {
  const { addTabId } = useTabBar();
  return (
    <Tab ref={ref} aria-label={props["aria-label"] ?? "Add tab"} value={addTabId} {...props}>
      {props.children || <Add />}
    </Tab>
  );
});

TabBarAddTab.displayName = "TabBar.AddTab";
